const HUB_HTML = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>ForCNFps</title>\n<!-- ForCNFps 选单：三张像素卡片，点一张就通知外层（DSH 插件）切到那个游戏，单独打开时直接跳到对应页面；\n     下面一条是灵敏度设置（鼠标 DPI + CS2/瓦罗兰特灵敏度，换算 eDPI、cm/360 和另一款游戏的等效值）。底层工具在 pixelkit.js。 -->\n<style>\n  * { margin:0; padding:0; }\n  html, body { height:100%; background:#1a1c2c; overflow:hidden; user-select:none; -webkit-user-select:none; }\n  canvas { position:fixed; inset:0; width:100%; height:100%; touch-action:none; image-rendering:pixelated; }\n</style>\n</head>\n<body>\n<canvas id=\"cv\"></canvas>\n<script>\n// 像素小游戏共用工具：低分辨率画布 + 整数倍放大、Sweetie 16 调色板、3×5 点阵字、中文像素字、图标、像素圆、面板、按钮、本地存储、8-bit 音效，\n// 以及按 CS2 / 瓦罗兰特 灵敏度换算准星移动的鼠标锁定。\n// 单独预览时由 <script src=\"pixelkit.js\"> 加载；scripts/build.mjs 打包时会把它内联进每个页面。\nwindow.PK = (() => {\n  const C = {\n    ink: '#1a1c2c', plum: '#5d275d', red: '#b13e53', orange: '#ef7d57', gold: '#ffcd75', lime: '#a7f070',\n    green: '#38b764', teal: '#257179', navy: '#29366f', blue: '#3b5dc9', sky: '#41a6f6', cyan: '#73eff7',\n    white: '#f4f4f4', fog: '#94b0c2', slate: '#566c86', dusk: '#333c57',\n  }\n  const RM = matchMedia('(prefers-reduced-motion: reduce)').matches\n  const store = {\n    get(k) { try { return localStorage.getItem(k) } catch (e) { return null } },\n    set(k, v) { try { localStorage.setItem(k, v) } catch (e) {} },\n  }\n  const json = k => { try { return JSON.parse(store.get(k) || 'null') } catch (e) { return null } }\n  const B4 = [[0, 8, 2, 10], [12, 4, 14, 6], [3, 11, 1, 9], [15, 7, 13, 5]]   // 4×4 Bayer 抖动矩阵\n\n  let g = null   // 当前绘制目标：screen() 创建的低分辨率缓冲\n\n  // 画布：所有内容画在约 targetW 像素宽的缓冲上，再无平滑整数倍放大到屏幕\n  function screen(cv, { targetW = 132, minH = 200 } = {}) {\n    const out = cv.getContext('2d'), buf = document.createElement('canvas')\n    const S = { cv, buf, g: buf.getContext('2d'), P: 2, W: 0, H: 0, OX: 0, OY: 0 }\n    g = S.g\n    S.resize = () => {\n      const dpr = Math.min(devicePixelRatio || 1, 3)\n      const dw = Math.round(innerWidth * dpr), dh = Math.round(innerHeight * dpr)\n      cv.width = dw; cv.height = dh\n      S.P = Math.max(2, Math.floor(Math.min(dw / targetW, dh / minH)))   // 一个美术像素占几个设备像素\n      S.W = Math.floor(dw / S.P); S.H = Math.floor(dh / S.P)\n      S.OX = Math.floor((dw - S.W * S.P) / 2); S.OY = Math.floor((dh - S.H * S.P) / 2)\n      buf.width = S.W; buf.height = S.H\n      S.g.imageSmoothingEnabled = false\n    }\n    S.toBuf = e => {\n      const r = cv.getBoundingClientRect()\n      return {\n        x: ((e.clientX - r.left) * (cv.width / r.width) - S.OX) / S.P,\n        y: ((e.clientY - r.top) * (cv.height / r.height) - S.OY) / S.P,\n      }\n    }\n    S.present = (shakeX = 0) => {\n      out.imageSmoothingEnabled = false\n      out.fillStyle = C.ink\n      out.fillRect(0, 0, cv.width, cv.height)\n      out.drawImage(buf, S.OX + shakeX * S.P, S.OY, S.W * S.P, S.H * S.P)\n    }\n    return S\n  }\n\n  // 3×5 点阵字（数字、英文、少量符号）\n  const F = {\n    '0': '111101101101111', '1': '010110010010111', '2': '111001111100111', '3': '111001111001111',\n    '4': '101101111001001', '5': '111100111001111', '6': '111100111101111', '7': '111001001010010',\n    '8': '111101111101111', '9': '111101111001111', '+': '000010111010000', '-': '000000111000000',\n    '%': '101001010100101', '.': '000000000000010', ':': '000010000010000', '/': '001001010100100',\n    '!': '010010010000010', '<': '001010100010001', '>': '100010001010100', ' ': '000000000000000',\n    '·': '000000010000000',\n    A: '010101111101101', B: '110101110101110', C: '011100100100011', D: '110101101101110',\n    E: '111100110100111', F: '111100110100100', G: '011100101101011', H: '101101111101101',\n    I: '111010010010111', J: '001001001101010', K: '101101110101101', L: '100100100100111',\n    M: '101111111101101', N: '110101101101101', O: '010101101101010', P: '110101110100100',\n    Q: '010101101110011', R: '110101110101101', S: '011100010001110', T: '111010010010010',\n    U: '101101101101111', V: '101101101101010', W: '101101111111101', X: '101101010101101',\n    Y: '101101010010010', Z: '111001010100111',\n  }\n  const btextW = (str, s = 1) => String(str).length * 4 * s - s\n  function btext(str, x, y, col, s = 1, align = 'left') {\n    str = String(str).toUpperCase()\n    const w = btextW(str, s)\n    if (align === 'center') x -= Math.floor(w / 2)\n    else if (align === 'right') x -= w\n    x = Math.round(x); y = Math.round(y)\n    g.fillStyle = col\n    for (const ch of str) {\n      const gl = F[ch]\n      if (gl) for (let i = 0; i < 15; i++) if (gl[i] === '1') g.fillRect(x + (i % 3) * s, y + Math.floor(i / 3) * s, s, s)\n      x += 4 * s\n    }\n  }\n\n  // 中文像素字：系统字体画在小画布上，按透明度阈值二值化后贴到像素网格。12px 用于正文，16px 用于标题\n  const textCache = new Map()\n  function ctextSprite(str, col, size, bold) {\n    const key = [str, col, size, bold].join('|')\n    let c = textCache.get(key)\n    if (c) return c\n    c = document.createElement('canvas')\n    const x2 = c.getContext('2d')\n    const font = `${bold ? '700 ' : ''}${size}px \"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",\"Noto Sans CJK SC\",sans-serif`\n    x2.font = font\n    c.width = Math.ceil(x2.measureText(str).width) + 2; c.height = size + 3\n    x2.font = font; x2.textBaseline = 'top'; x2.fillStyle = '#fff'\n    x2.fillText(str, 1, 1)\n    const img = x2.getImageData(0, 0, c.width, c.height), d = img.data\n    const n = parseInt(col.slice(1), 16)\n    for (let i = 0; i < d.length; i += 4) {\n      if (d[i + 3] >= (bold ? 140 : 80)) { d[i] = n >> 16; d[i + 1] = (n >> 8) & 255; d[i + 2] = n & 255; d[i + 3] = 255 }\n      else d[i + 3] = 0\n    }\n    x2.putImageData(img, 0, 0)\n    textCache.set(key, c)\n    return c\n  }\n  function ctext(str, x, y, col, { align = 'left', bold = false, size = 12, shadow = null } = {}) {\n    const c = ctextSprite(str, col, size, bold)\n    if (align === 'center') x -= Math.floor(c.width / 2)\n    else if (align === 'right') x -= c.width\n    x = Math.round(x); y = Math.round(y)\n    if (shadow) g.drawImage(ctextSprite(str, shadow, size, bold), x, y + 1)\n    g.drawImage(c, x, y)\n    return c.width\n  }\n\n  // 图标：字符串数组，# 为实心像素\n  const ICON = {\n    star: ['...#...', '...#...', '#######', '.#####.', '..###..', '.##.##.', '.#...#.'],\n    clock: ['..###..', '.#...#.', '#..#..#', '#..##.#', '#.....#', '.#...#.', '..###..'],\n    aim: ['...#...', '..#.#..', '.#...#.', '#..#..#', '.#...#.', '..#.#..', '...#...'],\n    spk: ['...#.....', '..##...#.', '####.#..#', '####.#..#', '####.#..#', '..##...#.', '...#.....'],\n    mute: ['...#.....', '..##.....', '####.#.#.', '####..#..', '####.#.#.', '..##.....', '...#.....'],\n    mouse: ['..#..', '.###.', '#.#.#', '#####', '#...#', '#...#', '.###.'],\n  }\n  function icon(name, x, y, col) {\n    g.fillStyle = col\n    ;(ICON[name] || name).forEach((row, j) => { for (let i = 0; i < row.length; i++) if (row[i] === '#') g.fillRect(x + i, y + j, 1, 1) })\n  }\n\n  // 像素圆环（中点画圆法）\n  function ring(cx, cy, r, col) {\n    g.fillStyle = col\n    let x = r, y = 0, err = 1 - r\n    while (x >= y) {\n      for (const [a, b] of [[x, y], [y, x], [-y, x], [-x, y], [-x, -y], [-y, -x], [y, -x], [x, -y]]) g.fillRect(cx + a, cy + b, 1, 1)\n      y++\n      if (err < 0) err += 2 * y + 1\n      else { x--; err += 2 * (y - x) + 1 }\n    }\n  }\n\n  // 圆角像素面板\n  function panel(x, y, w, h, border = C.dusk) {\n    g.fillStyle = border\n    g.fillRect(x + 1, y, w - 2, h); g.fillRect(x, y + 1, w, h - 2)\n    g.fillStyle = C.ink\n    g.fillRect(x + 1, y + 1, w - 2, h - 2)\n    g.fillStyle = C.navy\n    g.fillRect(x + 2, y + 1, w - 4, 1)\n  }\n\n  // 立体像素按钮，返回点击区域\n  function button(x, y, w, label, h = 18) {\n    g.fillStyle = C.red; g.fillRect(x + 1, y, w - 2, h); g.fillRect(x, y + 1, w, h - 2)\n    g.fillStyle = C.orange; g.fillRect(x + 1, y, w - 2, h - 2); g.fillRect(x, y + 1, w, h - 4)\n    g.fillStyle = C.gold; g.fillRect(x + 2, y + 1, w - 4, 1)\n    ctext(label, x + Math.floor(w / 2), y + 2, C.ink, { align: 'center', bold: true })\n    return { x, y, w, h }\n  }\n  const inRect = (x, y, r) => !!r && x >= r.x && x < r.x + r.w && y >= r.y && y < r.y + r.h\n\n  // 背景星点：固定种子，少数会闪\n  function starfield(W, H, seed = 20260403) {\n    let s = seed\n    const rnd = () => (s = (s * 16807) % 2147483647) / 2147483647\n    const out = []\n    for (let i = 0, n = Math.floor(W * H / 560); i < n; i++) out.push({ x: Math.floor(rnd() * W), y: Math.floor(rnd() * H), p: rnd() * 6.28, tw: rnd() < 0.25 })\n    return out\n  }\n  function drawStars(stars, now, skip) {\n    for (const s of stars) {\n      if (skip && inRect(s.x, s.y, skip)) continue\n      g.fillStyle = s.tw && !RM && Math.sin(now / 600 + s.p) > 0.7 ? C.fog : C.dusk\n      g.fillRect(s.x, s.y, 1, 1)\n    }\n  }\n\n  // 8-bit 音效（方波/三角波/噪声），静音设置三个游戏共用\n  const audio = (() => {\n    const KEY = 'dsh-arcade-mute-v1'\n    let ac = null, noiseBuf = null, muted = store.get(KEY) === '1'\n    function unlock() {\n      if (!ac) {\n        try { ac = new (window.AudioContext || window.webkitAudioContext)() } catch (e) { return }\n        noiseBuf = ac.createBuffer(1, Math.floor(ac.sampleRate * 0.2), ac.sampleRate)\n        const d = noiseBuf.getChannelData(0)\n        for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1\n      }\n      if (ac.state === 'suspended') ac.resume()\n    }\n    // semi：相对 C5 的半音数\n    function note(semi, dur = 0.07, type = 'square', vol = 0.05, delay = 0) {\n      if (muted || !ac) return\n      const t = ac.currentTime + delay, o = ac.createOscillator(), gn = ac.createGain()\n      o.type = type\n      o.frequency.setValueAtTime(523.25 * Math.pow(2, semi / 12), t)\n      gn.gain.setValueAtTime(vol, t)\n      gn.gain.setValueAtTime(vol, t + dur * 0.6)\n      gn.gain.exponentialRampToValueAtTime(0.0001, t + dur)\n      o.connect(gn).connect(ac.destination)\n      o.start(t); o.stop(t + dur + 0.02)\n    }\n    const arp = (semis, step, type) => semis.forEach((s, i) => note(s, step * 1.6, type, 0.045, i * step))\n    function noise(dur = 0.08, vol = 0.06, delay = 0) {\n      if (muted || !ac) return\n      const src = ac.createBufferSource(), gn = ac.createGain(), t = ac.currentTime + delay\n      src.buffer = noiseBuf\n      gn.gain.setValueAtTime(vol, t)\n      gn.gain.exponentialRampToValueAtTime(0.0001, t + dur)\n      src.connect(gn).connect(ac.destination)\n      src.start(t); src.stop(t + dur + 0.02)\n    }\n    return {\n      unlock, note, arp, noise,\n      get muted() { return muted },\n      toggle() { muted = !muted; store.set(KEY, muted ? '1' : '0'); if (!muted) { unlock(); note(12, 0.06) } },\n    }\n  })()\n\n  // 左下角「‹ 退出」按钮，返回点击区域；点了调用 goHome()\n  function exitButton(H) {\n    const x = 3, y = H - 16, w = 40, h = 14\n    g.fillStyle = C.dusk; g.fillRect(x + 1, y, w - 2, h); g.fillRect(x, y + 1, w, h - 2)\n    g.fillStyle = C.ink; g.fillRect(x + 1, y + 1, w - 2, h - 2)\n    btext('<', x + 4, y + 5, C.fog)\n    ctext('退出', x + 10, y + 1, C.fog)\n    return { x, y, w, h }\n  }\n  // 回 ForCNFps 主界面：先解锁鼠标，嵌在插件里就通知外层切回选单，单独打开时直接跳到 hub.html\n  function goHome() {\n    if (document.pointerLockElement) document.exitPointerLock()\n    if (window.parent !== window) window.parent.postMessage({ type: 'dsh-arcade:home' }, '*')\n    else location.href = 'hub.html'\n  }\n\n  // 右下角静音按钮，返回点击区域\n  function muteButton(W, H) {\n    const x = W - 13, y = H - 11\n    icon(audio.muted ? 'mute' : 'spk', x, y, C.slate)\n    return { x: x - 3, y: y - 3, w: 15, h: 13 }\n  }\n\n  // CS 风格准星：四根短线，带一圈深色描边；kick 是开枪时张开的像素数\n  function crosshair(x, y, kick = 0, col = C.lime) {\n    x = Math.round(x); y = Math.round(y)\n    const gap = 2 + kick, len = 3\n    const arms = [[x - gap - len, y, len, 1], [x + gap + 1, y, len, 1], [x, y - gap - len, 1, len], [x, y + gap + 1, 1, len]]\n    g.fillStyle = C.ink\n    for (const [ax, ay, w, h] of arms) g.fillRect(ax - 1, ay - 1, w + 2, h + 2)\n    g.fillStyle = col\n    for (const [ax, ay, w, h] of arms) g.fillRect(ax, ay, w, h)\n  }\n\n  // ---------- 灵敏度 ----------\n  // 游戏里每个鼠标计数转动「灵敏度 × yaw」度；fov 是 16:9 下的水平视野，用来把角度换成画面上的像素\n  const SENS_GAMES = {\n    cs: { name: 'CS2/CSGO', short: 'CS2', yaw: 0.022, fov: 106.26 },\n    val: { name: '瓦罗兰特', short: 'VAL', yaw: 0.07, fov: 103 },\n  }\n  const SENS_KEY = 'dsh-arcade-sens-v1', RAW_KEY = 'dsh-arcade-raw-v1'\n  const sens = {\n    games: SENS_GAMES,\n    get() {\n      const v = json(SENS_KEY) || {}\n      return { game: SENS_GAMES[v.game] ? v.game : 'cs', dpi: v.dpi > 0 ? v.dpi : 800, value: v.value > 0 ? v.value : 1.2, on: v.on === true }\n    },\n    set(v) { store.set(SENS_KEY, JSON.stringify({ game: v.game, dpi: v.dpi, value: v.value, on: v.on })) },\n    edpi: v => Math.round(v.dpi * v.value),\n    cm360: v => 360 / (v.value * SENS_GAMES[v.game].yaw) / v.dpi * 2.54,          // 转一圈要移动多少厘米\n    convert: (v, to) => v.value * SENS_GAMES[v.game].yaw / SENS_GAMES[to].yaw,    // 换算成另一款游戏的等效灵敏度\n    raw: () => store.get(RAW_KEY),     // '1' 原始输入已开启，'0' 只能普通锁定，'x' 锁定被拒绝，null 还没检测过\n  }\n\n  // 准星位置：灵敏度开关打开时，点一下锁定鼠标，按游戏公式把原始位移换算成准星移动；没开或没锁定时就跟着系统光标走\n  function pointer(S) {\n    const P = { x: 0, y: 0, locked: false }\n    let handler = null\n    S.cv.addEventListener('pointermove', e => { if (!P.locked) Object.assign(P, S.toBuf(e)) })\n    document.addEventListener('mousemove', e => {\n      if (!P.locked) return\n      const v = sens.get(), gm = SENS_GAMES[v.game]\n      const k = v.value * gm.yaw * (S.W / gm.fov)       // 每个计数走多少美术像素 = 度/计数 × 像素/度（画布宽度对应水平视野）\n      P.x = Math.max(0, Math.min(S.W - 1, P.x + e.movementX * k))\n      P.y = Math.max(0, Math.min(S.H - 1, P.y + e.movementY * k))\n    })\n    document.addEventListener('pointerlockchange', () => { P.locked = document.pointerLockElement === S.cv })\n    S.cv.addEventListener('pointerdown', e => {\n      e.preventDefault()\n      if (!P.locked) Object.assign(P, S.toBuf(e))\n      if (handler) handler(P, e)\n    })\n    P.onDown = fn => { handler = fn }\n    P.wantsLock = () => sens.get().on && !P.locked && !P.failed\n    // 优先要「原始输入」（不经过系统指针加速）；不支持就退回普通锁定，手感只能参考；连普通锁定都被拒绝，就本次不再尝试，准星跟着系统光标走\n    P.lock = () => {\n      if (!P.wantsLock() || !S.cv.requestPointerLock) return\n      const refuse = () => { P.failed = true; store.set(RAW_KEY, 'x') }\n      const basic = () => {\n        try {\n          const r = S.cv.requestPointerLock()\n          if (r && r.then) r.then(() => store.set(RAW_KEY, '0'), refuse)\n        } catch (e) { refuse() }\n      }\n      try {\n        const r = S.cv.requestPointerLock({ unadjustedMovement: true })\n        if (r && r.then) r.then(() => store.set(RAW_KEY, '1'), basic)\n        else document.addEventListener('pointerlockerror', refuse, { once: true })   // 老接口没有 Promise，只能靠事件判断\n      } catch (e) { basic() }\n    }\n    P.unlock = () => { if (P.locked) document.exitPointerLock() }\n    P.center = () => { P.x = S.W / 2; P.y = S.H / 2 }\n    return P\n  }\n\n  return { C, RM, B4, store, json, screen, btext, btextW, ctext, icon, ring, panel, button, inRect, starfield, drawStars, audio, muteButton, exitButton, goHome, crosshair, sens, pointer }\n})()\n</script>\n<script>\n(() => {\n  const { C, RM, B4, json, btext, ctext, icon, ring, panel, inRect, audio } = PK\n  const S = PK.screen(document.getElementById('cv'))\n  const g = S.g\n  let stars = [], cards = [], hover = null, muteRect = null\n\n  const GAMES = [\n    { id: 'schulte', title: '舒尔特斩', sub: 'SCHULTE', thumb: thumbSchulte },\n    { id: 'aim', title: '瞄准训练', sub: 'AIM TRAINER', thumb: thumbAim, best: () => json('aim-dots-best-v1') },\n    { id: 'hold', title: '架枪训练', sub: 'HOLD ANGLE', thumb: thumbHold, best: () => json('hold-angle-best-v1') },\n  ]\n\n  // ---------- 24×24 缩略图 ----------\n  function thumbSchulte(x, y) {\n    g.fillStyle = C.ink; g.fillRect(x, y, 24, 24)\n    ;[7, 2, 9, 4, 1, 6, 3, 8, 5].forEach((n, i) => {\n      const cx = x + 1 + (i % 3) * 8, cy = y + 1 + Math.floor(i / 3) * 8\n      g.fillStyle = C.navy; g.fillRect(cx, cy, 6, 6)\n      btext(n, cx + 2, cy + 1, n <= 3 ? C.slate : C.white)\n    })\n    for (let i = 0; i < 20; i++) {          // 一道刀光\n      g.fillStyle = C.red; g.fillRect(x + 2 + i, y + 21 - i, 2, 1)\n      g.fillStyle = C.gold; g.fillRect(x + 3 + i, y + 21 - i, 1, 1)\n    }\n  }\n  function thumbAim(x, y, now, active) {\n    g.fillStyle = C.ink; g.fillRect(x, y, 24, 24)\n    const r = 8, cx = x + 12, cy = y + 12 + (active && !RM ? Math.floor(now / 450) % 2 : 0)\n    const ramp = [C.plum, C.red, C.orange, C.gold]\n    for (let j = -r; j <= r; j++) for (let i = -r; i <= r; i++) {\n      const d = Math.hypot(i, j)\n      if (d > r + 0.25) continue\n      let col\n      if (d > r - 0.75) col = C.plum\n      else if (Math.hypot(i / r + 0.36, j / r + 0.4) < 0.25) col = C.white\n      else {\n        const nx = i / r, ny = j / r, nz = Math.sqrt(Math.max(0, 1 - nx * nx - ny * ny))\n        const l = Math.max(0, -0.45 * nx - 0.55 * ny + 0.7 * nz)\n        col = ramp[Math.max(0, Math.min(3, Math.floor(0.55 + l * 2.9 + (B4[(j + 32) & 3][(i + 32) & 3] / 16 - 0.5) * 0.85)))]\n      }\n      g.fillStyle = col; g.fillRect(cx + i, cy + j, 1, 1)\n    }\n  }\n  function thumbHold(x, y, now, active) {\n    g.fillStyle = C.gold; g.fillRect(x, y, 24, 24)\n    g.fillStyle = C.orange\n    for (let yy = 3; yy < 24; yy += 5) g.fillRect(x, y + yy, 24, 1)\n    for (let yy = 0; yy < 24; yy += 5) for (let xx = (yy / 5) % 2 ? 0 : 5; xx < 24; xx += 10) g.fillRect(x + xx, y + yy, 1, 4)\n    g.fillStyle = C.red; g.fillRect(x + 3, y + 6, 12, 18)\n    g.fillStyle = C.ink; g.fillRect(x + 4, y + 7, 10, 17)\n    // 探出半个脑袋\n    const peek = active && !RM && Math.floor(now / 600) % 3 === 0 ? 1 : 3\n    g.fillStyle = C.red; g.fillRect(x + 14 - peek, y + 12, peek, 1)\n    g.fillStyle = C.orange; g.fillRect(x + 14 - peek, y + 13, peek, 3)\n    g.fillStyle = C.green; g.fillRect(x + 14 - peek, y + 16, peek, 5)\n    // 准星\n    const cx = x + 12, cy = y + 14\n    g.fillStyle = C.ink\n    for (const [ax, ay, w, h] of [[cx - 5, cy, 3, 1], [cx + 3, cy, 3, 1], [cx, cy - 5, 1, 3], [cx, cy + 3, 1, 3]]) g.fillRect(ax - 1, ay - 1, w + 2, h + 2)\n    g.fillStyle = C.lime\n    for (const [ax, ay, w, h] of [[cx - 5, cy, 3, 1], [cx + 3, cy, 3, 1], [cx, cy - 5, 1, 3], [cx, cy + 3, 1, 3]]) g.fillRect(ax, ay, w, h)\n  }\n\n  // ---------- 布局与绘制 ----------\n  function resize() { S.resize(); stars = PK.starfield(S.W, S.H, 99) }\n\n  // 灵敏度设置页的草稿：输入框里是文字，失焦或回车时才校验写回\n  let view = 'menu', focus = null, fresh = false, draft = null, ui = {}\n  const SENS = PK.sens\n  function openSens() {\n    const v = SENS.get()\n    draft = { ...v, dpiText: String(v.dpi), valText: String(v.value) }\n    view = 'sens'; focus = null\n  }\n  const parsedDpi = () => { const d = parseInt(draft.dpiText, 10); return d >= 100 && d <= 32000 ? d : null }\n  const parsedVal = () => { const s = parseFloat(draft.valText); return s > 0 && s <= 50 ? Math.round(s * 1000) / 1000 : null }\n  function commit() {\n    draft.dpi = parsedDpi() || draft.dpi; draft.dpiText = String(draft.dpi)\n    draft.value = parsedVal() || draft.value; draft.valText = String(draft.value)\n    SENS.set(draft)\n  }\n  const live = () => ({ game: draft.game, dpi: parsedDpi() || draft.dpi, value: parsedVal() || draft.value })\n\n  function drawMenu(now, cx) {\n    const cw = Math.min(S.W - 12, 124), ch = 34, gap = 6\n    const total = 50 + GAMES.length * (ch + gap) + 24\n    let y = Math.max(4, Math.floor((S.H - total) / 2) - 6)\n    ctext('ForCNFps', cx, y, C.gold, { align: 'center', size: 16, bold: true, shadow: C.red })\n    btext('FPS TRAINING ARCADE', cx, y + 22, C.slate, 1, 'center')\n    ctext('等任务的时候来一局', cx, y + 30, C.fog, { align: 'center' })\n    y += 52\n\n    const x = Math.floor((S.W - cw) / 2)\n    cards = GAMES.map((game, i) => {\n      const r = { x, y: y + i * (ch + gap), w: cw, h: ch, id: game.id }\n      const on = hover === game.id\n      panel(r.x, r.y, r.w, r.h, on ? C.gold : C.dusk)\n      game.thumb(r.x + 5, r.y + 5, now, on)\n      g.fillStyle = C.dusk\n      g.fillRect(r.x + 4, r.y + 4, 26, 1); g.fillRect(r.x + 4, r.y + 29, 26, 1); g.fillRect(r.x + 4, r.y + 5, 1, 24); g.fillRect(r.x + 29, r.y + 5, 1, 24)\n      ctext(game.title, r.x + 35, r.y + 4, on ? C.gold : C.white)\n      btext(game.sub, r.x + 35, r.y + 22, C.slate)\n      const best = game.best && game.best()\n      if (best) {\n        btext(best.score, r.x + r.w - 6, r.y + 22, C.gold, 1, 'right')\n        icon('star', r.x + r.w - 15 - PK.btextW(best.score), r.y + 21, C.gold)\n      }\n      btext('>', r.x + r.w - 8, r.y + 9, on ? C.gold : C.slate)\n      return r\n    })\n\n    // 灵敏度入口\n    const v = SENS.get(), r = { x, y: y + GAMES.length * (ch + gap), w: cw, h: 20, id: 'sens' }\n    const on = hover === 'sens'\n    panel(r.x, r.y, r.w, r.h, on ? C.gold : C.dusk)\n    icon('mouse', r.x + 6, r.y + 6, v.on ? C.lime : C.slate)\n    ctext('灵敏度', r.x + 16, r.y + 3, on ? C.gold : C.white)\n    btext(v.on ? `${SENS.games[v.game].short} ${v.value} · ${v.dpi}` : 'OFF', r.x + r.w - 13, r.y + 8, v.on ? C.fog : C.slate, 1, 'right')\n    btext('>', r.x + r.w - 8, r.y + 8, on ? C.gold : C.slate)\n    cards.push(r)\n  }\n\n  // 画布上的输入框：数字用点阵字，聚焦时金色边框 + 闪烁光标；刚聚焦时整段高亮，第一下按键直接替换\n  function field(id, label, y, x, w) {\n    const bw = 56, bx = x + w - bw, text = id === 'dpi' ? draft.dpiText : draft.valText\n    const focused = focus === id\n    ui[id] = { x: bx, y, w: bw, h: 15 }\n    ctext(label, x, y + 1, C.fog)\n    g.fillStyle = focused ? C.gold : C.dusk; g.fillRect(bx, y, bw, 15)\n    g.fillStyle = C.ink; g.fillRect(bx + 1, y + 1, bw - 2, 13)\n    const tw = PK.btextW(text, 2)\n    if (focused && fresh && text) { g.fillStyle = C.navy; g.fillRect(bx + bw - 4 - tw - 1, y + 2, tw + 2, 11) }\n    btext(text, bx + bw - 4, y + 3, focused ? C.white : C.fog, 2, 'right')\n    if (focused && !fresh && Math.floor(performance.now() / 500) % 2 === 0) { g.fillStyle = C.gold; g.fillRect(bx + bw - 3, y + 2, 1, 11) }\n  }\n\n  function drawSens(now, cx) {\n    ui = {}\n    const pw = Math.min(S.W - 12, 124), px = Math.floor((S.W - pw) / 2)\n    let y = Math.max(4, Math.floor((S.H - 236) / 2))\n    ctext('灵敏度', cx, y, C.gold, { align: 'center', size: 16, shadow: C.red })\n    btext('MOUSE SENSITIVITY', cx, y + 21, C.slate, 1, 'center')\n    y += 32\n\n    // 游戏选择\n    const tw = Math.floor((pw - 4) / 2)\n    ;['cs', 'val'].forEach((id, i) => {\n      const r = { x: px + i * (tw + 4), y, w: tw, h: 16 }, on = draft.game === id\n      ui['tab_' + id] = r\n      g.fillStyle = on ? C.orange : C.dusk; g.fillRect(r.x, r.y, r.w, r.h)\n      if (on) { g.fillStyle = C.gold; g.fillRect(r.x, r.y, r.w, 1) }\n      if (id === 'cs') btext(SENS.games.cs.name, r.x + Math.floor(r.w / 2), r.y + 6, on ? C.ink : C.fog, 1, 'center')\n      else ctext(SENS.games.val.name, r.x + Math.floor(r.w / 2), r.y + 1, on ? C.ink : C.fog, { align: 'center' })\n    })\n    y += 23\n\n    field('dpi', '鼠标 DPI', y, px, pw); y += 20\n    field('val', '游戏灵敏度', y, px, pw); y += 22\n\n    // 换算结果\n    const v = live(), other = v.game === 'cs' ? 'val' : 'cs'\n    g.fillStyle = C.dusk; g.fillRect(px, y, pw, 40)\n    btext('EDPI', px + 5, y + 5, C.fog); btext(SENS.edpi(v), px + pw - 5, y + 5, C.white, 1, 'right')\n    btext('CM/360', px + 5, y + 14, C.fog); btext(SENS.cm360(v).toFixed(1), px + pw - 5, y + 14, C.white, 1, 'right')\n    if (other === 'val') ctext('= 瓦罗兰特', px + 4, y + 22, C.fog)\n    else { btext('= CS2/CSGO', px + 5, y + 26, C.fog) }\n    btext(SENS.convert(v, other).toFixed(3), px + pw - 5, y + 26, C.gold, 1, 'right')\n    y += 46\n\n    // 开关：是否在游戏里按这个灵敏度移动准星\n    ctext('按游戏手感瞄准', px, y + 1, C.fog)\n    const sw = { x: px + pw - 24, y: y + 2, w: 24, h: 11 }\n    ui.toggle = sw\n    g.fillStyle = draft.on ? C.green : C.dusk; g.fillRect(sw.x + 1, sw.y, sw.w - 2, sw.h); g.fillRect(sw.x, sw.y + 1, sw.w, sw.h - 2)\n    g.fillStyle = draft.on ? C.white : C.slate; g.fillRect(draft.on ? sw.x + sw.w - 10 : sw.x + 2, sw.y + 2, 8, sw.h - 4)\n    y += 17\n\n    const raw = SENS.raw()\n    const RAW = { '1': ['原始输入：已开启', C.green], '0': ['原始输入：不可用', C.orange], x: ['鼠标锁定被拒绝', C.red] }\n    const [rawText, rawCol] = RAW[raw] || ['原始输入：未检测', C.slate]\n    ctext(rawText, px, y, rawCol)\n    y += 15\n    ctext('游戏里点一下锁定鼠标', px, y, C.slate)\n    y += 14\n    ctext('按 ESC 解锁', px, y, C.slate)\n    y += 18\n    ui.done = PK.button(px, y, pw, '完成')\n  }\n\n  function frame() {\n    const now = performance.now(), cx = Math.floor(S.W / 2)\n    g.fillStyle = C.ink; g.fillRect(0, 0, S.W, S.H)\n    PK.drawStars(stars, now)\n    if (view === 'menu') drawMenu(now, cx)\n    else drawSens(now, cx)\n    muteRect = PK.muteButton(S.W, S.H)\n    S.present()\n    requestAnimationFrame(frame)\n  }\n\n  // ---------- 输入 ----------\n  const cardAt = p => cards.find(r => inRect(p.x, p.y, r))\n  S.cv.addEventListener('pointermove', e => {\n    const p = S.toBuf(e)\n    if (view === 'menu') {\n      const r = cardAt(p)\n      hover = r ? r.id : null\n      S.cv.style.cursor = r ? 'pointer' : 'default'\n    } else {\n      const over = Object.entries(ui).find(([, r]) => inRect(p.x, p.y, r))\n      S.cv.style.cursor = !over ? 'default' : over[0] === 'dpi' || over[0] === 'val' ? 'text' : 'pointer'\n    }\n  })\n  S.cv.addEventListener('pointerleave', () => { hover = null })\n  S.cv.addEventListener('pointerdown', e => {\n    e.preventDefault()\n    window.focus()\n    audio.unlock()\n    const p = S.toBuf(e)\n    if (inRect(p.x, p.y, muteRect)) { audio.toggle(); return }\n\n    if (view === 'sens') {\n      const hit = Object.keys(ui).find(k => inRect(p.x, p.y, ui[k]))\n      if (hit === 'dpi' || hit === 'val') { if (focus && hit !== focus) commit(); focusField(hit); return }\n      blurField()\n      if (hit === 'tab_cs' || hit === 'tab_val') { draft.game = hit.slice(4); draft.on = true; commit(); audio.note(7, 0.04) }\n      else if (hit === 'toggle') { draft.on = !draft.on; commit(); audio.note(draft.on ? 12 : 0, 0.05) }\n      else if (hit === 'done') { commit(); view = 'menu'; audio.note(7, 0.05) }\n      return\n    }\n\n    const r = cardAt(p)\n    if (!r) return\n    if (r.id === 'sens') { openSens(); audio.note(7, 0.04); return }\n    audio.arp([0, 7, 12], 0.04)\n    if (window.parent !== window) window.parent.postMessage({ type: 'dsh-arcade:open', game: r.id }, '*')\n    else if (r.id !== 'schulte') location.href = r.id + '.html'   // 单独预览时直接跳过去\n  })\n\n  // 输入框背后是一个看不见的真输入框：键盘、粘贴、输入法都走它，画布只负责显示\n  const input = document.createElement('input')\n  Object.assign(input.style, { position: 'fixed', left: '-1000px', top: '0', opacity: '0' })\n  input.setAttribute('inputmode', 'decimal')\n  input.autocomplete = 'off'\n  document.body.appendChild(input)\n  function focusField(id) { focus = id; fresh = true; input.value = ''; input.focus() }\n  function blurField() { if (focus) commit(); focus = null; input.blur() }\n  input.addEventListener('input', () => {\n    if (!focus) return\n    let t = input.value.replace(focus === 'dpi' ? /[^0-9]/g : /[^0-9.]/g, '')\n    const dot = t.indexOf('.')\n    if (dot >= 0) t = t.slice(0, dot + 1) + t.slice(dot + 1).replace(/\\./g, '')\n    t = t.slice(0, focus === 'dpi' ? 5 : 6)\n    input.value = t\n    draft[focus === 'dpi' ? 'dpiText' : 'valText'] = t\n    fresh = false\n    draft.on = true\n  })\n  // 回车确认，Tab 跳到另一个，Esc 放弃这次修改；刚聚焦时按退格清空\n  input.addEventListener('keydown', e => {\n    if (!focus) return\n    if (e.key === 'Backspace' && fresh) { draft[focus === 'dpi' ? 'dpiText' : 'valText'] = ''; fresh = false }\n    else if (e.key === 'Enter') { e.preventDefault(); blurField() }\n    else if (e.key === 'Tab') { e.preventDefault(); commit(); focusField(focus === 'dpi' ? 'val' : 'dpi') }\n    else if (e.key === 'Escape') { draft.dpiText = String(draft.dpi); draft.valText = String(draft.value); focus = null; input.blur() }\n  })\n  input.addEventListener('blur', () => { if (focus) { commit(); focus = null } })\n\n  addEventListener('resize', resize)\n  resize()\n  requestAnimationFrame(frame)\n})()\n</script>\n</body>\n</html>\n"
